    99→            if (task.spec_ref) {
   100→              const specResult = index.resolve(task.spec_ref);
   101→              if (specResult.ok) {
   102→                const specItem = specResult.item as {
   103→                  title: string;
   104→                  acceptance_criteria?: Array<{ description?: string; given?: string }>;
   105→                };
   106→                spec_context = {
   107→                  spec_ref: task.spec_ref,
   108→                  title: specItem.title,
   109→                  acceptance_criteria: (specItem.acceptance_criteria ?? []).map((ac, i) => ({
   110→                    id: `ac-${i + 1}`,
   111→                    description: ac.description ?? ac.given ?? '',
   112→                  })),
   113→                };
   114→              }
   115→            }
   116→          }
   117→        } catch {
   118→          // Non-critical — spec context is optional
   119→        }
   120→      }
   121→
   122→      // AC: @ui-session-stream ac-4 — Include budget info
   123→      let budget: { max_per_cycle: number; started_this_cycle: number } | null = null;
   124→      try {
   125→        budget = await getBudget(ctx.specDir, resolution.id);
   126→      } catch {
   127→        // No budget configured — that's fine
   128→      }
   129→
   130→      return {
   131→        ...detail,
   132→        task_id: metadata?.task_id,
   133→        agent_id: metadata?.agent_id,
   134→        trigger: metadata?.trigger ?? 'legacy',
   135→        spec_context,
   136→        budget,
   137→      };
   138→    })
   139→
   140→    // Get session events
   141→    .get('/:id/events', async ({ params, query, error: errorResponse, projectContext }) => {
   142→      const ctx = await initContext(projectContext.path);
   143→
   144→      const resolution = await resolveSessionId(ctx.specDir, params.id);
   145→      if (!resolution.ok) {
   146→        if (resolution.error === 'ambiguous') {
   147→          return errorResponse(400, {
   148→            error: 'ambiguous_id',
   149→            message: `Ambiguous session ID: ${params.id} matches ${resolution.matches.length} sessions`,
   150→            suggestion: 'Provide a longer prefix to uniquely identify the session',
   151→          });
   152→        }
   153→        return errorResponse(404, {
   154→          error: 'not_found',
   155→          message: `Session not found: ${params.id}`,
   156→          suggestion: 'Use GET /api/sessions to list available sessions',
   157→        });
   158→      }
   159→
   160→      let events = await readEvents(ctx.specDir, resolution.id);
   161→
   162→      // Deduplicate phased tool calls
   163→      events = deduplicatePhasedToolCalls(events);
   164→
   165→      // Filter by since_seq if provided (for incremental loading)
   166→      const sinceSeq = query.since_seq !== undefined ? parseInt(query.since_seq, 10) : undefined;
   167→      if (sinceSeq !== undefined && !isNaN(sinceSeq)) {
   168→        events = events.filter(e => e.seq > sinceSeq);
   169→      }
   170→
   171→      return {
   172→        events,
   173→        total: events.length,
   174→      };
   175→    }, {
   176→      query: t.Object({
   177→        since_seq: t.Optional(t.String()),
   178→      }),
   179→    });
   180→}
